<script setup>
import {ref,watch,computed} from 'vue';import Modal from './Modal.vue';import Icon from './Icon.vue';import {api,mutate,notify} from '../lib/api.js';import {today,addDays,money} from '../lib/format.js';import {clientSchema,serviceSchema,expenseSchema,paymentSchema,subscriptionSchema,referrerSchema,commissionSchema,lineSchema} from '../../shared/contracts.js';import {eurosToCents,totals,ratio,commissionRate,commissionAmount} from '../../shared/money.js';
const props=defineProps({open:Boolean,kind:String,record:Object,context:Object});const emit=defineEmits(['close','saved']);
const form=ref({}),lookups=ref({clients:[],projects:[],categories:[],referrers:[]}),error=ref(''),busy=ref(false),file=ref(),newCategory=ref(''),linkType=ref(''),linkId=ref(''),linkRows=ref([]),invoiceRows=ref([]),rateTouched=ref(false),projectHint=ref('');
const names={clients:'CLIENT',services:'PRESTATION',expenses:'DÉPENSE',payments:'PAIEMENT',documents:'DOCUMENT',subscriptions:'ABONNEMENT',referrers:'APPORTEUR',commissions:'COMMISSION'};
const title=computed(()=>`${props.record?'MODIFIER':'AJOUTER'} ${names[props.kind]||''}.`);
watch(()=>props.open,async open=>{if(!open)return;error.value='';file.value=null;newCategory.value='';linkType.value='';linkId.value='';rateTouched.value=false;projectHint.value='';const c=props.context||{},r=props.record||{};
form.value={name:'',contact:'',email:'',phone:'',address:'',siret:'',iban:'',conventionDate:'',referrerId:c.referrerId||'',label:'',baseCents:0,rateBps:0,status:{referrers:'occasional',commissions:'awaiting'}[props.kind]||'prospect',notes:'',description:'',categoryId:'',unitCents:0,pricing:'fixed',frequency:props.kind==='subscriptions'?'monthly':'once',indicative:false,active:true,includesMaintenance:false,supplier:'',date:today(),dueDate:addDays(today(),30),netCents:0,vatBps:0,category:props.kind==='subscriptions'?'Hébergement':'Logiciels',paid:true,method:'transfer',comment:'',clientId:c.clientId||'',projectId:c.projectId||'',invoiceId:c.invoiceId||'',amountCents:c.amountCents||0,reference:'',requestKey:crypto.randomUUID(),startDate:today(),nextDate:addDays(today(),30),...r};
form.value.amount=(form.value.unitCents/100).toFixed(2);if(props.kind==='expenses')form.value.amount=(form.value.netCents/100).toFixed(2);if(['payments','subscriptions'].includes(props.kind))form.value.amount=(form.value.amountCents/100).toFixed(2);if(props.kind==='commissions'){form.value.amount=(form.value.baseCents/100).toFixed(2);form.value.rate=String((form.value.rateBps||commissionRate(form.value.baseCents))/100);rateTouched.value=!!props.record;}form.value.vat=String(form.value.vatBps/100);form.value.referrerId=form.value.referrerId||'';
try{lookups.value=await api('/lookups');if(!form.value.categoryId)form.value.categoryId=lookups.value.categories[0]?.id||'';if(props.kind==='payments'){const r=await api('/invoices?limit=100');invoiceRows.value=r.rows.filter(i=>!['draft','cancelled','paid'].includes(i.status));}}catch(e){error.value=e.message;}});
const base=computed(()=>{try{return eurosToCents(form.value.amount??'');}catch{return null;}});
const suggestedRate=computed(()=>base.value===null?null:commissionRate(base.value)/100);
const commissionPreview=computed(()=>{try{return commissionAmount(base.value,eurosToCents(form.value.rate??''));}catch{return null;}});
watch(base,value=>{if(props.kind==='commissions'&&!rateTouched.value&&value!==null)form.value.rate=String(commissionRate(value)/100);});
async function pickProject(){projectHint.value='';const id=form.value.projectId;if(!id)return;try{const p=await api('/projects/'+id);const t=totals(p.items.map(i=>lineSchema.parse(i)),p.discountBps);const collected=Math.min(p.payments.reduce((a,x)=>a+x.amountCents,0),t.total);const assiette=t.total?ratio(collected,t.net,t.total):0;form.value.clientId=p.clientId;form.value.label=p.title;form.value.amount=(assiette/100).toFixed(2);if(!rateTouched.value)form.value.rate=String(commissionRate(assiette)/100);form.value.status=collected>0?'due':'awaiting';projectHint.value=`Encaissé ${money(collected,true)} sur ${money(t.total,true)} TTC · assiette HT ${money(assiette,true)}.`;}catch(e){error.value=e.message;}}
watch(linkType,async type=>{linkId.value='';linkRows.value=[];if(!type)return;try{linkRows.value=(await api('/'+type+'?limit=100')).rows;}catch(e){error.value=e.message;}});
const eligibleProjects=computed(()=>lookups.value.projects.filter(p=>!form.value.clientId||p.clientId===form.value.clientId));
const eligibleInvoices=computed(()=>invoiceRows.value.filter(i=>(!form.value.clientId||i.clientId===form.value.clientId)&&(!form.value.projectId||i.projectId===form.value.projectId)));
function pickInvoice(){const i=invoiceRows.value.find(i=>i.id===form.value.invoiceId);if(i){form.value.clientId=i.clientId;form.value.projectId=i.projectId||'';form.value.amount=((i.totalCents-i.payments.reduce((a,p)=>a+p.amountCents,0))/100).toFixed(2);}}
async function upload(id){const data=new FormData();data.append('file',file.value);const links={...props.context};if(props.kind==='expenses')links.expenseId=id;if(linkType.value&&linkId.value)links[({clients:'clientId',projects:'projectId',quotes:'quoteId',invoices:'invoiceId',expenses:'expenseId',referrers:'referrerId'})[linkType.value]]=linkId.value;const params=new URLSearchParams(Object.entries(links).filter(([k,v])=>['clientId','projectId','quoteId','invoiceId','expenseId','referrerId'].includes(k)&&v));return mutate('/documents?'+params,'POST',data,'Document ajouté.');}
async function save(){error.value='';busy.value=true;try{let result;
  if(props.kind==='documents'){if(!file.value)throw new Error('Sélectionnez un fichier.');result=await upload();}
  else {let data={...form.value};if(props.kind==='clients')data=clientSchema.parse(data);
    if(props.kind==='services'){if(newCategory.value.trim()){const cat=await api('/categories',{method:'POST',body:{name:newCategory.value.trim()}});form.value.categoryId=cat.id;data.categoryId=cat.id;newCategory.value='';}data=serviceSchema.parse({...data,unitCents:eurosToCents(data.amount)});}
    if(props.kind==='expenses')data=expenseSchema.parse({...data,netCents:eurosToCents(data.amount),vatBps:eurosToCents(data.vat)});
    if(props.kind==='payments')data=paymentSchema.parse({...data,projectId:data.projectId||undefined,invoiceId:data.invoiceId||undefined,amountCents:eurosToCents(data.amount)});
    if(props.kind==='subscriptions')data=subscriptionSchema.parse({...data,projectId:data.projectId||undefined,amountCents:eurosToCents(data.amount),vatBps:eurosToCents(data.vat)});
    if(props.kind==='referrers')data=referrerSchema.parse(data);
    if(props.kind==='commissions')data=commissionSchema.parse({...data,projectId:data.projectId||undefined,invoiceId:data.invoiceId||undefined,baseCents:eurosToCents(data.amount),rateBps:eurosToCents(data.rate)});
    result=await mutate('/'+props.kind+(props.record?'/'+props.record.id:''),props.record?'PATCH':'POST',data);
    if(props.kind==='expenses'&&file.value){try{await upload(result.id);}catch(e){notify('Dépense enregistrée ; pièce jointe à réessayer : '+e.message,'error');}}
  }
  emit('saved',result);emit('close');
}catch(e){error.value=e.issues?e.issues.map(i=>i.message).join(' · '):e.message;}finally{busy.value=false;}}
</script>
<template><Modal :open="open" :title="title" @close="!busy&&emit('close')"><form @submit.prevent="save"><div class="form-grid" v-if="kind==='clients'"><label>Entreprise / nom<input v-model="form.name" required maxlength="200" autofocus></label><label>Contact<input v-model="form.contact" maxlength="200"></label><label>Email<input v-model="form.email" type="email" required></label><label>Téléphone<input v-model="form.phone" type="tel"></label><label class="span-2">Adresse<textarea v-model="form.address"/></label><label>SIRET<input v-model="form.siret" inputmode="numeric" maxlength="14" placeholder="14 chiffres (facultatif)"></label><label>Statut<select v-model="form.status"><option value="prospect">Prospect</option><option value="active">Actif</option><option value="archived">Archivé</option></select></label><label class="span-2">Apporté par<select v-model="form.referrerId"><option value="">Personne · contact direct</option><option v-for="r in lookups.referrers" :key="r.id" :value="r.id">{{r.name}}</option></select><span class="field-note">Rattache les futures commissions d’apport à cette relation.</span></label><label class="span-2">Notes internes<textarea v-model="form.notes"/></label></div><div v-else-if="kind==='services'" class="form-grid"><label class="span-2">Nom de la prestation<input v-model="form.name" required></label><label>Catégorie<select v-model="form.categoryId"><option v-for="c in lookups.categories" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Ou nouvelle catégorie<input v-model="newCategory" placeholder="Nom de catégorie"></label><label class="span-2">Description<textarea v-model="form.description"/></label><label>Prix HT (€)<input v-model="form.amount" inputmode="decimal" required></label><label>Tarification<select v-model="form.pricing"><option value="fixed">Prix fixe</option><option value="hourly">Prix horaire</option><option value="custom">Sur devis</option></select></label><label>Fréquence<select v-model="form.frequency"><option value="once">Prestation unique</option><option value="monthly">Mensuelle</option><option value="yearly">Annuelle</option></select></label><div><label class="check-label"><input type="checkbox" v-model="form.indicative">Prix indicatif</label><label class="check-label" style="margin-top:14px"><input type="checkbox" v-model="form.active">Prestation active</label></div><label class="check-label span-2"><input type="checkbox" v-model="form.includesMaintenance">Le prix comprend déjà la maintenance</label></div><div v-else-if="kind==='expenses'" class="form-grid"><label class="span-2">Fournisseur<input v-model="form.supplier" required></label><label>Date de facture<input type="date" v-model="form.date" required></label><label>Échéance<input type="date" v-model="form.dueDate" required></label><label>Montant HT (€)<input v-model="form.amount" inputmode="decimal" required></label><label>TVA (%)<input v-model="form.vat" inputmode="decimal" required></label><label>Catégorie<input v-model="form.category" list="expense-categories" required><datalist id="expense-categories"><option>Hébergement</option><option>Logiciels</option><option>Matériel</option><option>Nom de domaine</option><option>Services</option><option>Autre</option></datalist></label><label>Moyen de paiement<select v-model="form.method"><option value="transfer">Virement</option><option value="card">Carte</option><option value="cash">Espèces</option><option value="other">Autre</option></select></label><label class="check-label span-2"><input type="checkbox" v-model="form.paid">Dépense déjà payée</label><label class="span-2">Commentaire<textarea v-model="form.comment"/></label><label class="span-2">Pièce jointe (facultative)<input type="file" accept="application/pdf,image/jpeg,image/png" @change="file=$event.target.files[0]"><span class="field-note">PDF, JPG ou PNG · 10 Mo maximum</span></label></div><div v-else-if="kind==='payments'" class="form-grid"><label class="span-2">Client<select v-model="form.clientId" required :disabled="!!context?.clientId"><option value="" disabled>Choisir un client</option><option v-for="c in lookups.clients" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label class="span-2">Facture<select v-model="form.invoiceId" @change="pickInvoice" :disabled="!!context?.invoiceId"><option value="">Paiement sur le projet (sans facture)</option><option v-for="i in eligibleInvoices" :key="i.id" :value="i.id">{{i.reference}} · {{i.title}}</option></select></label><label class="span-2">Projet<select v-model="form.projectId" :disabled="!!context?.projectId||!!form.invoiceId"><option value="">Sans projet</option><option v-for="p in eligibleProjects" :key="p.id" :value="p.id">{{p.title}}</option></select></label><label>Montant reçu (€)<input v-model="form.amount" inputmode="decimal" required></label><label>Date du paiement<input type="date" v-model="form.date" :max="today()" required></label><label>Mode de paiement<select v-model="form.method"><option value="transfer">Virement</option><option value="card">Carte</option><option value="cash">Espèces</option><option value="other">Autre</option></select></label><label>Référence bancaire<input v-model="form.reference"></label><label class="span-2">Commentaire<textarea v-model="form.comment"/></label></div><div v-else-if="kind==='subscriptions'" class="form-grid"><label class="span-2">Client<select v-model="form.clientId" required><option value="" disabled>Choisir un client</option><option v-for="c in lookups.clients" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label class="span-2">Nom de l’abonnement<input v-model="form.name" required></label><label>Montant HT (€)<input v-model="form.amount" inputmode="decimal" required></label><label>Fréquence<select v-model="form.frequency"><option value="monthly">Mensuelle</option><option value="yearly">Annuelle</option></select></label><label>Catégorie<input v-model="form.category" required></label><label>Début<input v-model="form.startDate" type="date" required></label><label>Prochaine échéance<input v-model="form.nextDate" type="date" required></label><label>TVA (%)<input v-model="form.vat" inputmode="decimal" required></label></div><div v-else-if="kind==='referrers'" class="form-grid"><label class="span-2">Nom de l’apporteur<input v-model="form.name" required maxlength="200" autofocus></label><label>Email<input v-model="form.email" type="email"></label><label>Téléphone<input v-model="form.phone" type="tel"></label><label class="span-2">Adresse<textarea v-model="form.address"/></label><label>Type d’apport<select v-model="form.status"><option value="occasional">Occasionnel · mise en relation ponctuelle</option><option value="regular">Régulier · activité habituelle</option><option value="archived">Archivé</option></select><span class="field-note">Un apport régulier suppose un statut professionnel : l’apporteur facture alors ses commissions.</span></label><label>SIRET<input v-model="form.siret" inputmode="numeric" maxlength="14" placeholder="14 chiffres"><span class="field-note">Obligatoire pour un apporteur régulier.</span></label><label>Convention signée le<input type="date" v-model="form.conventionDate"><span class="field-note">Une convention d’apport d’affaires, même d’une page, sécurise la relation.</span></label><label>IBAN<input v-model="form.iban" maxlength="200" placeholder="Pour le virement de la commission"></label><label class="span-2">Notes<textarea v-model="form.notes"/></label></div><div v-else-if="kind==='commissions'" class="form-grid"><label class="span-2">Apporteur<select v-model="form.referrerId" required><option value="" disabled>Choisir un apporteur</option><option v-for="r in lookups.referrers" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label>Client apporté<select v-model="form.clientId" required @change="form.projectId=''"><option value="" disabled>Choisir un client</option><option v-for="c in lookups.clients" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Projet<select v-model="form.projectId" @change="pickProject"><option value="">Sans projet</option><option v-for="p in eligibleProjects" :key="p.id" :value="p.id">{{p.title}}</option></select><span class="field-note">Reprend automatiquement le montant déjà encaissé.</span></label><label class="span-2">Libellé<input v-model="form.label" maxlength="200" placeholder="Nom du client par défaut"></label><label>Montant HT encaissé (€)<input v-model="form.amount" inputmode="decimal" required><span class="field-note">{{projectHint||'L’assiette est ce que le client vous a réellement versé, hors taxes.'}}</span></label><label>Taux (%)<input v-model="form.rate" inputmode="decimal" required @input="rateTouched=true"><span class="field-note">Barème pour ce montant : {{suggestedRate??'—'}} %.</span></label><label>Date de l’encaissement<input type="date" v-model="form.date" :max="today()" required></label><label>Statut<select v-model="form.status"><option value="awaiting">En attente de l’encaissement client</option><option value="due">À verser · le client a payé</option><option value="cancelled">Annulée</option></select></label><p class="section-note span-2">Commission à verser : <strong>{{commissionPreview===null?'—':money(commissionPreview,true)}}</strong>. Elle se calcule sur l’encaissement réel et se verse après règlement du client.</p><label class="span-2">Notes<textarea v-model="form.notes"/></label></div><div v-else-if="kind==='documents'"><div class="upload-zone" @dragover.prevent @drop.prevent="file=$event.dataTransfer.files[0]"><Icon name="Upload" :size="30"/><h3>Vos documents, au même endroit.</h3><p>Glissez un PDF, un JPG ou un PNG · 10 Mo maximum</p><input type="file" accept="application/pdf,image/jpeg,image/png" @change="file=$event.target.files[0]" aria-label="Choisir un document"><p v-if="file">{{file.name}}</p></div><div class="form-grid" style="margin-top:20px" v-if="!context||!Object.keys(context).length"><label>Associer à<select v-model="linkType"><option value="">Bibliothèque générale</option><option value="clients">Client</option><option value="projects">Projet</option><option value="quotes">Devis</option><option value="invoices">Facture</option><option value="expenses">Dépense</option><option value="referrers">Apporteur d’affaires</option></select></label><label v-if="linkType">Dossier<select v-model="linkId" required><option value="" disabled>Choisir un dossier</option><option v-for="r in linkRows" :key="r.id" :value="r.id">{{r.name||r.title||r.supplier}} {{r.reference||''}}</option></select></label></div></div><p class="form-error" v-if="error" role="alert">{{error}}</p><div class="form-actions"><button type="button" class="btn" :disabled="busy" @click="emit('close')">Annuler</button><button class="btn primary" :disabled="busy">{{busy?'Enregistrement…':'Enregistrer'}}<Icon name="Check"/></button></div></form></Modal></template>
